import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import {
  HEADER_RULES,
  IMMUTABLE,
  REDIRECTS,
  decodeEntities,
  headerRuleProblems,
  headersFile,
  htmlFileFor,
  isIgnored,
  pageContentText,
  redirectsFile,
  verifyExport,
} from './cf-finalize'
import type { SitemapPlan } from './generate-sitemaps'

describe('_redirects', () => {
  it('carries next.config.js redirects as 301s, with one splat', () => {
    expect(redirectsFile()).toBe(
      [
        '# Generated by scripts/cf-finalize.ts; do not edit.',
        '/explore / 301',
        '/docs/articles /articles 301',
        '/docs/articles/* /articles/:splat 301',
        '',
      ].join('\n')
    )
    for (const rule of REDIRECTS) expect(rule.from.split('*').length - 1).toBeLessThanOrEqual(1)
  })
})

describe('_headers', () => {
  it('is a valid rule set', () => {
    expect(headerRuleProblems(HEADER_RULES)).toEqual([])
  })

  it('keeps every non-canonical host out of the index and sends HSTS everywhere', () => {
    const file = headersFile()
    expect(file).toContain(
      '/*\n  Strict-Transport-Security: max-age=63072000\n\n' +
        'https://:version.:subdomain.workers.dev/*\n  X-Robots-Tag: noindex, nofollow\n\n' +
        'https://next.alexwelcing.com/*\n  X-Robots-Tag: noindex, nofollow'
    )
    expect(file).not.toMatch(/https:\/\/alexwelcing\.com/)
  })

  it('marks only the content-hashed prefix immutable', () => {
    const immutable = HEADER_RULES.filter((rule) => rule.headers['Cache-Control'] === IMMUTABLE)
    expect(immutable.map((rule) => rule.pattern)).toEqual(['/_next/static/*'])
    const cached = Object.fromEntries(
      HEADER_RULES.map((rule) => [rule.pattern, rule.headers['Cache-Control']])
    )
    for (const media of ['/images/*', '/background/*']) {
      expect(cached[media]).toBe('public, max-age=604800, stale-while-revalidate=2592000')
    }
    for (const data of ['/arc/*', '/search/*']) {
      expect(cached[data]).toBe('public, max-age=300, stale-while-revalidate=86400')
    }
    expect(cached['/fonts/*']).toMatch(/^public, max-age=3600\b/)
    // The film pages are HTML; only the media files under /videos/articles are long-lived.
    expect(cached['/videos/*']).toBeUndefined()
  })

  it('rejects two splats, immutable unhashed paths, overlaps and duplicate placeholders', () => {
    const problems = headerRuleProblems([
      { pattern: '/worlds/*/*.ktx2', headers: { 'Cache-Control': IMMUTABLE } },
      { pattern: '/images/*', headers: { 'Cache-Control': IMMUTABLE } },
      { pattern: '/images/og/*', headers: { 'Cache-Control': 'no-store' } },
      { pattern: 'https://:a.:a.workers.dev/*', headers: { 'X-Robots-Tag': 'noindex' } },
      { pattern: 'images/*', headers: { 'X-Robots-Tag': 'noindex' } },
    ])
    expect(problems).toEqual([
      '/worlds/*/*.ktx2: 2 splats (only one is allowed per rule)',
      '/worlds/*/*.ktx2: immutable outside the content-hashed prefixes',
      '/images/*: immutable outside the content-hashed prefixes',
      'https://:a.:a.workers.dev/*: a placeholder is used twice',
      'images/*: a rule is a path or an https:// URL',
      'Cache-Control rules /images/* and /images/og/* overlap',
    ])
  })
})

describe('helpers', () => {
  it('maps routes to the files auto-trailing-slash serves', () => {
    expect(htmlFileFor('/')).toBe('index.html')
    expect(htmlFileFor('/about')).toBe('about.html')
    expect(htmlFileFor('/articles/x/')).toBe('articles/x.html')
  })

  it('ignores only the listed build logs', () => {
    expect(isIgnored('images/article-videos/series-generation-log.json')).toBe(true)
    expect(isIgnored('images/article-videos/a.mp4')).toBe(false)
    expect(isIgnored('images/article-videos/sub/a.json')).toBe(false)
    expect(isIgnored('assets/asset-costs.json')).toBe(true)
  })

  it('decodes the entities React escapes text with', () => {
    expect(
      decodeEntities('Q&amp;A &lt;b&gt; &quot;x&quot; it&#x27;s &#39;y&#39; &#8212; &zz;')
    ).toBe("Q&A <b> \"x\" it's 'y' — &zz;")
  })

  it('reads #arc-page-content up to __NEXT_DATA__ only', () => {
    const html =
      '<div id="__next"><canvas></canvas><div id="arc-page-content"><h1>Title</h1>' +
      '<p>One &amp; two<!-- -->three</p><script>var x = 1</script></div></div>' +
      '<script id="__NEXT_DATA__" type="application/json">{"props":"hidden body"}</script>'
    expect(pageContentText(html)).toBe('Title One & twothree')
    expect(pageContentText('<div id="__next"></div>')).toBeNull()
  })
})

describe('verifyExport', () => {
  let root: string
  afterEach(() => fs.rmSync(root, { recursive: true, force: true }))

  const write = (relative: string, content: string) => {
    const file = path.join(root, relative)
    fs.mkdirSync(path.dirname(file), { recursive: true })
    fs.writeFileSync(file, content)
  }
  const BODY =
    'A paragraph long enough to count as the body of a page that really rendered its text.'
  const page = (body: string, robots = 'index, follow') =>
    `<html><head><meta name="robots" content="${robots}"/><meta name="description" content="d"/>` +
    `<link rel="canonical" href="https://alexwelcing.com/x"/></head><body><div id="__next">` +
    `<div id="arc-page-content"><main>${body}</main></div></div>` +
    `<script id="__NEXT_DATA__" type="application/json">{}</script></body></html>`

  function fixture() {
    root = fs.mkdtempSync(path.join(os.tmpdir(), 'cf-finalize-'))
    const blocks = [
      { t: 'h', x: 'Heading' },
      { t: 'p', x: `It's a record & ${BODY}` },
    ]
    write('public/arc/records/rec.json', JSON.stringify({ blocks }))
    write('public/arc/records/thin.json', JSON.stringify({ blocks: [{ t: 'p', x: BODY }] }))
    write('public/arc/archive.json', JSON.stringify({ records: [{ slug: 'rec' }] }))
    write('public/arc/media.json', JSON.stringify({ films: ['film'] }))
    write('public/resumes/cv.pdf', 'pdf')
    write(
      'lib/generated/search-manifest.json',
      JSON.stringify({ assets: { chunks: '/search/chunks.h.json' } })
    )
    write(
      'out/search/chunks.h.json',
      JSON.stringify({
        docs: [
          { slug: 'rec', target: { type: 'article' } },
          { slug: 'about', target: { type: 'data', panel: 'about' } },
        ],
      })
    )
    write('out/index.html', page(`<h1>Home</h1><p>${BODY}</p>`))
    write('out/404.html', page(`<p>${BODY}</p>`, 'noindex, follow'))
    write('out/articles/rec.html', page(`<h2>Heading</h2><p>It&#x27;s a record &amp; ${BODY}</p>`))
    write('out/articles/thin.html', page(`<p>${BODY}</p>`, 'noindex,follow'))
    write('out/videos/film.html', page(`<p>${BODY}</p>`))
    for (const route of ['index', 'articles/rec', 'articles/thin', 'videos/film']) {
      write(`out/_next/data/BUILD/${route}.json`, '{}')
    }
    for (const file of [
      'favicon.ico',
      'robots.txt',
      'social-preview.png',
      'og-default.png',
      'video-sitemap.xml',
      'arc/archive.json',
      'arc/archive-full.json',
      'arc/media.json',
      'resumes/cv.pdf',
    ]) {
      write(`out/${file}`, 'x')
    }
    write(
      'out/sitemap.xml',
      ['/', '/articles/rec', '/videos/film']
        .map((route) => `<loc>https://alexwelcing.com${route === '/' ? '' : route}</loc>`)
        .join('')
    )
    const plan: SitemapPlan = {
      urls: [{ path: '/' }, { path: '/articles/rec' }, { path: '/videos/film' }],
      films: [],
      noindex: [{ slug: 'thin', reason: 'test' }],
    }
    return plan
  }

  it('passes a complete export', () => {
    const plan = fixture()
    const report = verifyExport(root, plan, 'https://alexwelcing.com')
    expect(report.problems).toEqual([])
    expect(report.pages).toBe(4)
  })

  it('names every gap: lost body text, wrong robots, unexported links, leaks, missing files', () => {
    const plan = fixture()
    write('out/articles/rec.html', page('<h2>Heading</h2><p>Only part of it</p>'))
    write('out/articles/thin.html', page(`<p>${BODY}</p>`))
    fs.rmSync(path.join(root, 'out/videos/film.html'))
    fs.rmSync(path.join(root, 'out/_next/data/BUILD/articles/thin.json'))
    fs.rmSync(path.join(root, 'out/resumes/cv.pdf'))
    write('out/api/vector-search.html', 'leak')
    write(
      'public/arc/archive.json',
      JSON.stringify({ records: [{ slug: 'rec' }, { slug: 'gone' }] })
    )

    const { problems } = verifyExport(root, plan, 'https://alexwelcing.com')
    expect(problems).toEqual(
      expect.arrayContaining([
        'out/api exists: the server surface leaked into the export',
        expect.stringMatching(/^\/articles\/rec: #arc-page-content holds only/),
        expect.stringMatching(/^\/articles\/rec: 1 record blocks are not in the HTML/),
        '/videos/film: out/videos/film.html is missing',
        '/articles/thin: robots "index, follow", expected noindex',
        '/articles/gone (from arc/archive.json) is not exported',
        '/videos/film (from arc/media.json) is not exported',
        'out/resumes/cv.pdf is missing',
        'out/sitemap.xml lists https://alexwelcing.com/videos/film, which is not exported',
      ])
    )
  })

  it('requires the client-navigation data of every openable page', () => {
    const plan = fixture()
    fs.rmSync(path.join(root, 'out/_next/data/BUILD/articles/rec.json'))
    expect(verifyExport(root, plan, 'https://alexwelcing.com').problems).toEqual([
      '/articles/rec (from arc/archive.json) has no out/_next/data/BUILD/articles/rec.json',
    ])
  })
})
